<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
final class RecipientLetterMigration {
 const ID='033_install_donor_families';
 public static function checksum(){ $files=array_merge([__FILE__,get_theme_file_path('/inc/letter-pages.php'),get_theme_file_path('/templates/donor-families.html'),get_theme_file_path('/assets/css/letter-pages.css')],glob(get_theme_file_path('/assets/letter-pages/*')));sort($files);$hash=hash_init('sha256');foreach($files as $file){if(!is_file($file))fail('Write to a Transplant Recipient theme assets missing.');hash_update($hash,basename($file).file_get_contents($file));}return hash_final($hash); }
 public static function plan(){
  preflight();if(!function_exists('ed_donor_families_content'))fail('Matching Write to a Transplant Recipient theme is required.');$page=get_page_by_path('donor-families');$id=$page?(int)$page->ID:0;if($id&&!current_user_can('edit_post',$id))fail('Write to a Transplant Recipient page cannot be edited.');if(!$id&&!current_user_can('publish_pages'))fail('Cannot create Write to a Transplant Recipient page.');
  $ops=[['field'=>'post_content','before'=>$id?$page->post_content:null,'after'=>ed_donor_families_content()],['field'=>'_wp_page_template','before'=>$id?get_post_meta($id,'_wp_page_template',true):'','after'=>'donor-families']];
  $ops=[$ops[1],$ops[0]];
  foreach(['tcb_editor_disabled'=>'1','tcb_editor_enabled'=>''] as $field=>$value)$ops[]=['field'=>$field,'before'=>$id?get_post_meta($id,$field,true):'','after'=>$value];
  return ['page_id'=>$id,'checksum'=>self::checksum(),'operations'=>$ops];
 }
 public static function preview(){ $state=history()[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('033 checksum changed.');$plan=self::plan();$plan['actor']=get_current_user_id();$plan['created']=time();update_option('edm_donor_families_preview',$plan,false);return $plan; }
 private static function read($id,$field){return $field==='post_content'?get_post_field('post_content',$id):get_post_meta($id,$field,true);}
 public static function run(){preflight();$token=lock_acquire();try{
  $h=history();$state=$h[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('033 checksum changed.');if(($state['status']??'')==='completed')return 'Write to a Transplant Recipient already installed; subsequent editorial changes preserved.';
  $preview=get_option('edm_donor_families_preview');if(!$preview||$preview['actor']!==get_current_user_id()||$preview['checksum']!==self::checksum()||$preview['created']<time()-DAY_IN_SECONDS)fail('Fresh Write to a Transplant Recipient preview required.');
  $saved=$state['plan']??$preview;$id=(int)($state['destination_id']??$saved['page_id']);$plan=self::plan();if(!$id&&!empty($state['run_id'])&&$plan['page_id']&&get_post_meta($plan['page_id'],'_edm_donor_families_run_id',true)===$state['run_id'])$id=$plan['page_id'];if($plan['page_id']!==$id)fail('Write to a Transplant Recipient destination changed after preview.');if(fingerprint(array_column($plan['operations'],'after','field'))!==fingerprint(array_column($saved['operations'],'after','field')))fail('Write to a Transplant Recipient payload changed after preview.');
  foreach($saved['operations'] as $op){$current=$id?self::read($id,$op['field']):($op['field']==='post_content'?null:'');if($current!==$op['before']&&$current!==$op['after']&&!($saved['page_id']===0&&$op['field']==='post_content'&&$current===''))fail('Write to a Transplant Recipient changed after preview: '.$op['field']);if(isset($state['operations'][$op['field']])&&$current!==$op['after'])fail('Applied Write to a Transplant Recipient field was edited.');}
  $state=array_merge($state,['status'=>'running','checksum'=>self::checksum(),'actor'=>get_current_user_id(),'run_id'=>$state['run_id']??wp_generate_uuid4(),'started'=>$state['started']??time(),'destination_id'=>$id,'plan'=>$saved]);$h[self::ID]=$state;lock_check($token);save_history($h);
  if(!$id){$id=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_name'=>'donor-families','post_title'=>'Write to a Transplant Recipient','post_content'=>'','meta_input'=>['_edm_key'=>'page.donor_families','_edm_donor_families_run_id'=>$state['run_id']]],true);if(is_wp_error($id)||!$id)fail('Could not create Write to a Transplant Recipient page.');$state['destination_id']=$id;$h[self::ID]=$state;save_history($h);}
  foreach($saved['operations'] as $op){lock_check($token);$current=self::read($id,$op['field']);if($current!==$op['after']){if($current!==$op['before']&&!($saved['page_id']===0&&$op['field']==='post_content'&&$current===''))fail('Write to a Transplant Recipient changed during migration.');if($op['field']==='post_content'){$result=wp_update_post(['ID'=>$id,'post_content'=>wp_slash($op['after'])],true);if(is_wp_error($result))fail($result->get_error_message());}elseif($op['after']==='')delete_post_meta($id,$op['field']);else update_post_meta($id,$op['field'],$op['after']);}if(self::read($id,$op['field'])!==$op['after'])fail('Write to a Transplant Recipient verification failed: '.$op['field']);$state['operations'][$op['field']]=true;$h[self::ID]=$state;save_history($h);}
  $state['status']='completed';$state['completed']=time();$h[self::ID]=$state;save_history($h);return 'Editable Write to a Transplant Recipient content and template installed.';
 }finally{lock_release($token);}}
}
foreach(['preview','run'] as $mode)add_action('admin_post_edm_donor_families_'.$mode,function()use($mode){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('edm_donor_families_'.$mode);try{if($mode==='run'&&(empty($_POST['backup'])||empty($_POST['replace'])))fail('Backup and replacement acknowledgment required.');$result=$mode==='preview'?RecipientLetterMigration::preview():RecipientLetterMigration::run();update_option('edm_donor_families_notice',is_string($result)?$result:'Preview ready.',false);}catch(\Throwable $e){update_option('edm_donor_families_notice',$e->getMessage(),false);}wp_safe_redirect(admin_url('tools.php?page=eyedonation-migrations#edm-donor_families'));exit;});
add_action('admin_footer',function(){if(($_GET['page']??'')!=='eyedonation-migrations'||!current_user_can('manage_options'))return;echo '<div class="wrap" id="edm-donor_families"><h2>033 — Editable Write to a Transplant Recipient page</h2><p>Replaces /donor-families/ with the approved block layout or creates that page when missing. Assigns the Write to a Transplant Recipient template and disables the builder only for this page. Existing builder data is retained. Status: '.esc_html(history()[RecipientLetterMigration::ID]['status']??'pending').'</p><p>'.esc_html(get_option('edm_donor_families_notice','')).'</p>';foreach(['preview'=>'Preview Write to a Transplant Recipient','run'=>'Install / Resume Write to a Transplant Recipient'] as $mode=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_donor_families_'.$mode.'">';wp_nonce_field('edm_donor_families_'.$mode);if($mode==='run')echo '<label><input type="checkbox" name="backup" value="1" required> I have a recoverable backup.</label><br><label><input type="checkbox" name="replace" value="1" required> Replace the Write to a Transplant Recipient content with the previewed design.</label>';submit_button($label);echo '</form>';}$p=get_option('edm_donor_families_preview');if($p)echo '<details><summary>Current / proposed page fields</summary><pre>'.esc_html(wp_json_encode($p,JSON_PRETTY_PRINT)).'</pre></details>';echo '</div>';});
